python3 - <<'PY'
import pathlib,re
roots=[pathlib.Path(x) for x in ['app','components','hooks','screens']]
pat=re.compile(r'\b(useQuery|useMutation|useAction|useConvex)\s*\(')
imp=re.compile(r"from ['\"]convex/react['\"]")
count=0; files={}
for root in roots:
  for p in root.rglob('*'):
    if p.suffix not in ('.ts','.tsx'): continue
    s=p.read_text(errors='ignore').splitlines()
    hits=[]
    for i,l in enumerate(s,1):
      if pat.search(l): hits.append((i,l.strip()))
    if hits:
      files[str(p)]=hits; count += len(hits)
print('count',count,'files',len(files))
for p,hits in files.items():
  print(p)
  for i,l in hits: print(f'  {i}: {l}')
PY

